-- // SINGLE RUN GUARD - FIXED
-- // Jika script dijalankan ulang, run sebelumnya otomatis dihapus / close

local RUN_KEY = "ZHUB_MAIN_RUNNING"
local SCRIPT_ID = debug.getinfo(1, "S").source

-- Cari dan hentikan instance sebelumnya
local function killPreviousInstance()
    -- Method 1: Paksa stop semua thread yang menjalankan script yang sama
    if debug and debug.getregistry then
        local reg = debug.getregistry()
        for i = 1, 100 do
            local success, obj = pcall(function() return reg[i] end)
            if success and type(obj) == "thread" then
                local success2, info = pcall(function() return debug.getinfo(obj) end)
                if success2 and info and info.source == SCRIPT_ID and obj ~= coroutine.running() then
                    pcall(function() coroutine.close(obj) end)
                end
            end
        end
    end
    
    -- Method 2: Hentikan loop utama jika ada
    if _G[RUN_KEY] and type(_G[RUN_KEY]) == "function" then
        pcall(_G[RUN_KEY])
    end
    
    -- Method 3: Bersihkan event connections dan threads
    if _G.ZHUB_CONNECTIONS then
        for _, conn in ipairs(_G.ZHUB_CONNECTIONS) do
            pcall(function() if conn and conn.Disconnect then conn:Disconnect() end end)
        end
        _G.ZHUB_CONNECTIONS = nil
    end
    
    if _G.ZHUB_THREADS then
        for _, thread in ipairs(_G.ZHUB_THREADS) do
            pcall(function() task.cancel(thread) end)
        end
        _G.ZHUB_THREADS = nil
    end
end

-- Jalankan kill sebelum menjalankan instance baru
killPreviousInstance()

-- Setup cleanup function untuk instance baru
local connections = {}
local threads = {}
local instances = {}

local function trackConnection(conn)
    if conn then table.insert(connections, conn) end
    return conn
end

local function trackThread(thread)
    if thread then table.insert(threads, thread) end
    return thread
end

local function trackInstance(obj)
    if obj then table.insert(instances, obj) end
    return obj
end

-- Simpan fungsi cleanup
_G[RUN_KEY] = function()
    for _, conn in ipairs(connections) do
        pcall(function() if conn and conn.Disconnect then conn:Disconnect() end end)
    end
    for _, thread in ipairs(threads) do
        pcall(function() task.cancel(thread) end)
    end
    for _, obj in ipairs(instances) do
        pcall(function() if obj and obj.Destroy then obj:Destroy() end end)
    end
    table.clear(connections)
    table.clear(threads)
    table.clear(instances)
    _G[RUN_KEY] = nil
end

-- Simpan data untuk akses global (opsional)
_G.ZHUB_CONNECTIONS = connections
_G.ZHUB_THREADS = threads

